{
  "metadati": {
    "data_sintetica": "2026-04-19",
    "chiave_indagine": null,
    "descrizione": "L'utente chiede se l'Indagine trimestrale su posti vacanti ed ore lavorate (VELA), codice PSN IST-01381, sia obbligatoria e se la mancata partecipazione comporti sanzioni, comunicando il codice utente {{cod_utente_1}}. L'agente indica che obbligo ed eventuali sanzioni devono essere verificati nelle informazioni ufficiali o con l'assistenza."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Per l'Indagine trimestrale su posti vacanti ed ore lavorate (VELA) vorrei sapere se la compilazione è obbligatoria e se ci sono sanzioni se nn partecipiamo."
    },
    {
      "sender": "Agente",
      "testo": "Per verificare se la partecipazione sia obbligatoria e se siano previste eventuali sanzioni, occorre fare riferimento alle informazioni ufficiali dell'indagine o sottoporre il caso all'assistenza."
    },
    {
      "sender": "Utente",
      "text": "Il codice PSN è IST-01381 e il nostro codice utente è {{cod_utente_1}}. Quindi qual è la regola per la nostra impresa?"
    },
    {
      "sender": "Agente",
      "testo": "Per l'indagine con codice PSN IST-01381, la posizione della singola impresa va verificata dall'assistenza sulla base delle informazioni ufficiali disponibili."
    },
    {
      "sender": "Utente",
      "testo": "Mi serve soprattutto capire se la mancata risposta può portare a una sanzione."
    },
    {
      "sender": "Agente",
      "testo": "Non posso confermare in questa sede se la mancata risposta comporti una sanzione. L'eventuale applicabilità va verificata nelle informazioni ufficiali dell'Indagine trimestrale su posti vacanti ed ore lavorate (VELA) o con l'assistenza, indicando il codice utente {{cod_utente_1}}."
    }
  ]
}
